package net.officefloor.hq.app.holiday;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** The date is already on the sheet's list of holidays. */
@ResponseStatus(HttpStatus.CONFLICT)
public class DuplicateHolidayException extends RuntimeException {}
package net.officefloor.hq.app.holiday;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/holidays")
public class HolidayController {

    /** A holiday on the sheet. */
    public record HolidayView(Long id, LocalDate date) {
        static HolidayView of(Holiday h) {
            return new HolidayView(h.getId(), h.getDate());
        }
    }

    /** A holiday's date (yyyy-mm-dd). */
    public record HolidayRequest(@NotBlank @Pattern(regexp = "\\d{4}-\\d{2}-\\d{2}") String date) {

        LocalDate dateValue() {
            return LocalDate.parse(date);
        }
    }

    private final HolidayService service;

    public HolidayController(HolidayService service) {
        this.service = service;
    }

    @GetMapping
    public List<HolidayView> list(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.holidays(sheetId).stream().map(HolidayView::of).toList();
    }

    @PostMapping
    public HolidayView add(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid HolidayRequest request) {
        return HolidayView.of(service.add(sheetId, user, request.dateValue()));
    }
}
package net.officefloor.hq.app.holiday;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A holiday on a sheet, each date at most once. */
@Entity
@Table(name = "holiday")
public class Holiday {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "holiday_date", nullable = false)
    private LocalDate date;

    protected Holiday() {}

    public Holiday(String sheetId, LocalDate date) {
        this.sheetId = sheetId;
        this.date = date;
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public LocalDate getDate() { return date; }
}
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface HolidayRepository extends JpaRepository<Holiday, Long> {

    List<Holiday> findBySheetIdOrderByDateAsc(String sheetId);

    boolean existsBySheetIdAndDate(String sheetId, LocalDate date);
}
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * A sheet's list of holidays, each date at most once. A claim's due-by, fixed when it is added, is
 * moved past them: the next day that is not a holiday. A holiday added later moves no due-by.
 */
@Service
public class HolidayService {

    private final SheetRepository sheets;
    private final HolidayRepository holidays;
    private final Audit audit;

    public HolidayService(SheetRepository sheets, HolidayRepository holidays, Audit audit) {
        this.sheets = sheets;
        this.holidays = holidays;
        this.audit = audit;
    }

    /** The sheet's holidays, earliest first. */
    @Transactional(readOnly = true)
    public List<Holiday> holidays(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId);
    }

    /** Add the date to the sheet's holidays; refused for a date already on the list. */
    @Transactional
    public Holiday add(String sheetId, String user, LocalDate date) {
        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        if (holidays.existsBySheetIdAndDate(sheetId, date)) throw new DuplicateHolidayException();
        Holiday saved = holidays.saveAndFlush(new Holiday(sheetId, date));
        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user.strip() + " date=" + date);
        return saved;
    }

    /** The date, or when it is a holiday on the sheet, the next day that is not. */
    @Transactional(readOnly = true)
    public LocalDate pastHolidays(String sheetId, LocalDate date) {
        Set<LocalDate> days = holidays.findBySheetIdOrderByDateAsc(sheetId).stream()
                .map(Holiday::getDate).collect(Collectors.toSet());
        LocalDate d = date;
        while (days.contains(d)) d = d.plusDays(1);
        return d;
    }
}
    /** The PENDING claim a steward approves or rejects; refused when not PENDING or not a steward. */
    private Claim pendingForSteward(String sheetId, String user, Long id) {
        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusRefusedException();
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
        return claim;
    }

    /**
     * Give an opened claim its number: the sheet's next, or while the sheet numbers by period, the next
     * within the period its due-by falls in (in no period: the next in the sheet's X sequence).
     */
    private void number(Sheet sheet, Claim claim) {
        if (!sheet.numbersByPeriod()) {
            claim.setNumber(sheet.nextClaimNumber());
            return;
        }
        String period = periodOn(sheet.getId(), claim.getDueBy());
        claim.setNumberWithin(period, claims.lastNumberWithin(sheet.getId(), period) + 1);
    }

    /**
     * The due-by a claim of the person dated on the date is fixed with: its date plus their own terms, else
     * their grade's then, moved past the sheet's holidays now to the next day that is not one.
     */
    private LocalDate dueByOf(String sheetId, Person person, LocalDate on) {
        return holidays.pastHolidays(sheetId, on.plusDays(person.getTerms() != null ? person.getTerms()
                : settings.termsFor(sheetId, person.gradeOn(on), on)));
    }

    /** The name of the sheet's period the date falls in; empty when in none. */
    private String periodOn(String sheetId, LocalDate date) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
                .filter(p -> p.contains(date))
                .map(Period::getName)
                .findFirst().orElse("");
    }

    /**
     * A claim's figure now: the due fixed when it was settled, else the rate figure bound by its person's
     * last statement, else its rate figure (no floor, no charge); null when it has none.
package db.migration;

import java.sql.ResultSet;
import java.sql.Statement;
import org.flywaydb.core.api.migration.BaseJavaMigration;
import org.flywaydb.core.api.migration.Context;

/**
 * A claim's place in its sheet's list: claims are listed by it, newest first. A claim added takes
 * the next from claim_listed_seq, and so does one moved to another person, which is then listed as
 * their newest. Existing claims keep their order by id; the sequence starts after the last of them.
 */
public class V29__claim_listed extends BaseJavaMigration {

    @Override
    public void migrate(Context context) throws Exception {
        long last;
        try (Statement query = context.getConnection().createStatement();
                ResultSet rows = query.executeQuery("SELECT COALESCE(MAX(id), 0) FROM claim")) {
            rows.next();
            last = rows.getLong(1);
        }
        try (Statement alter = context.getConnection().createStatement()) {
            alter.execute("CREATE SEQUENCE claim_listed_seq START WITH " + (last + 1));
            alter.execute("ALTER TABLE claim ADD COLUMN listed BIGINT");
            alter.execute("UPDATE claim SET listed = id");
            alter.execute("ALTER TABLE claim ALTER COLUMN listed SET DEFAULT NEXT VALUE FOR claim_listed_seq");
            alter.execute("ALTER TABLE claim ALTER COLUMN listed SET NOT NULL");
            alter.execute("CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed)");
        }
    }
}
